impl<T: FnOnce(char) -> bool> ParsePrimitive for T {
    fn peek(self, parser: &Parser) -> bool {
        parser.source[parser.location.index..]
            .chars()
            .next()
            .is_some_and(self)
    }

    fn take(self, parser: &mut Parser) -> bool {
        parser.source[parser.location.index..]
            .chars()
            .next()
            .filter(|c| self(*c))
            .inspect(|c| parser.location.advance(*c))
            .is_some()
    }

    fn len(&self) -> usize {
        1
    }
}

