fn impl_parse_variants(&self) -> Result<TokenStream, Error> {
    let variants = self
        .item
        .variants
        .iter()
        .map(|variant| self.impl_parse_variant(variant))
        .collect::<Result<Vec<_>, _>>()?;

    Ok(quote! {
        return #(#variants)else*
        else {
            Err(input.mismatch(format!("expected {}", std::any::type_name::<Self>())))
        };
    })
}

